import { Routes } from '@angular/router';
import { MovieList } from './movie-list/movie-list';
import { ScreenPlaceholder } from './screen-placeholder';
import { SeatSelection } from './seat-selection/seat-selection';

export const appRoutes: Routes = [
  { path: '', pathMatch: 'full', component: MovieList },
  { path: 'screenings/:id/seats', component: SeatSelection },
  { path: 'screenings/:id/summary', component: ScreenPlaceholder },
  { path: 'screenings/:id/checkout', component: ScreenPlaceholder },
  { path: 'confirmation', component: ScreenPlaceholder },
  { path: '**', redirectTo: '' },
];
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}
const ISO_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export const WEEKDAY_NAMES = [
  'Sunday',
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday',
];
const MONTH_NAMES = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
];

/** Show date `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
export function formatShowDate(isoDate: string, time: string): string {
  const date = parseIsoDate(isoDate);
  if (!date) {
    return `${isoDate} ${time}`;
  }
  return `${WEEKDAY_NAMES[date.getDay()]} ${date.getDate()} ${MONTH_NAMES[date.getMonth()]} ${time}`;
}

export function toIsoDate(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

/** Returns the local date for a valid `YYYY-MM-DD` string, or null when it is not a real date. */
export function parseIsoDate(value: string | null): Date | null {
  if (!value || !ISO_DATE_PATTERN.test(value)) {
    return null;
  }
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  const isReal =
    date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
  return isReal ? date : null;
}

export function startOfToday(): Date {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
}

export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}
import { Component, Injectable, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA, MatSnackBar } from '@angular/material/snack-bar';

export const TOAST_DURATION_MS = 4000;

/** Content of the toast: a snack bar showing one message. */
@Component({
  selector: 'app-toast',
  template: `<span data-testid="toast">{{ message }}</span>`,
})
export class ToastContent {
  readonly message = inject<{ message: string }>(MAT_SNACK_BAR_DATA).message;
}

/** Shows short messages. A new message replaces the one on screen. */
@Injectable({ providedIn: 'root' })
export class Toast {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastContent, {
      data: { message },
      duration: TOAST_DURATION_MS,
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie, Screening } from './models';

const API_BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class CinemaApi {
  private readonly http = inject(HttpClient);

  movies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${API_BASE_URL}/movies`);
  }

  movie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${API_BASE_URL}/movies/${id}`);
  }

  screeningsOn(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${API_BASE_URL}/screenings`, { params: { date } });
  }

  screening(id: string): Observable<Screening> {
    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${encodeURIComponent(id)}`);
  }
}
import { Component } from '@angular/core';

/** Stand-in for the screens that later tickets implement. */
@Component({
  selector: 'app-screen-placeholder',
  template: '',
})
export class ScreenPlaceholder {}

import { Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, Observable, catchError, map, switchMap, tap } from 'rxjs';
import { CinemaApi } from '../cinema-api.service';
import { formatShowDate } from '../dates';
import { Movie, Screening } from '../models';
import { Toast } from '../toast';
import { CouchCell, SeatCell, SeatState, buildAuditorium, seatIdsOf } from './auditorium';

interface LoadedScreening {
  screening: Screening;
  movie: Movie;
}

/** Painted state of a seat or couch: `selected` replaces a free state. */
export type DisplayState = SeatState | 'selected';

export interface SelectedRowLine {
  row: number;
  seats: string;
}

const MAX_SEATS = 10;

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toast = inject(Toast);

  /** Identifiers of the selected seats; a couch contributes both of its identifiers. */
  private readonly selectedIds = signal<ReadonlySet<string>>(new Set());

  private readonly loaded = toSignal(
    this.route.paramMap.pipe(
      map((params) => params.get('id') ?? ''),
      tap(() => this.selectedIds.set(new Set())),
      switchMap((id) => this.load(id)),
    ),
    { initialValue: null },
  );

  /** Null while the screening is loading; a failed load redirects to `/`. */
  readonly page = computed(() => {
    const current = this.loaded();
    if (!current) {
      return null;
    }
    return {
      showDate: formatShowDate(current.screening.date, current.screening.time),
      rows: buildAuditorium(current.screening.occupiedSeats),
    };
  });

  readonly selectedCount = computed(() => this.selectedIds().size);

  /** One `Row <r>: <seats>` line per row with a selection, rows in ascending order. */
  readonly selectedRows = computed<SelectedRowLine[]>(() => {
    const lines: SelectedRowLine[] = [];
    for (const row of this.page()?.rows ?? []) {
      const seats = row.cells.flatMap((cell) => {
        if (cell.kind !== 'seat' && cell.kind !== 'couch') {
          return [];
        }
        if (!this.isSelected(cell)) {
          return [];
        }
        return [cell.kind === 'seat' ? `${cell.column}` : `${cell.columnStart}-${cell.columnEnd}`];
      });
      if (seats.length > 0) {
        lines.push({ row: row.row, seats: seats.join(', ') });
      }
    }
    return lines;
  });

  /** Selects or deselects a seat or couch as one unit; unavailable ones are ignored. */
  toggle(cell: SeatCell | CouchCell): void {
    if (cell.state === 'unavailable') {
      return;
    }
    const ids = seatIdsOf(cell);
    const selected = new Set(this.selectedIds());
    if (this.isSelected(cell)) {
      ids.forEach((id) => selected.delete(id));
    } else {
      if (selected.size + ids.length > MAX_SEATS) {
        this.toast.show(`Maximum ${MAX_SEATS} seats per booking`);
        return;
      }
      ids.forEach((id) => selected.add(id));
    }
    this.selectedIds.set(selected);
  }

  isSelected(cell: SeatCell | CouchCell): boolean {
    return this.selectedIds().has(seatIdsOf(cell)[0]);
  }

  displayState(cell: SeatCell | CouchCell): DisplayState {
    if (cell.state === 'unavailable') {
      return 'unavailable';
    }
    return this.isSelected(cell) ? 'selected' : cell.state;
  }

  private load(id: string): Observable<LoadedScreening> {
    return this.api.screening(id).pipe(
      switchMap((screening) =>
        this.api.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
      ),
      catchError(() => {
        void this.router.navigate(['/']);
        return EMPTY;
      }),
    );
  }
}
