export const COUCH_PRICE = 89;

/** Price of one seat by row (section 5.4). */
export function seatPrice(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  return 39;
}

/** Prices are always printed with two decimals and the `PLN` suffix. */
export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

import { Injectable, inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { COUCH_ROW, seatId } from './seat-selection/auditorium';
import { COUCH_PRICE, seatPrice } from './pricing';

/** The booking in progress, kept in `sessionStorage` (section 3.1). */
export interface Booking {
  screeningId: number;
  /** Seat identifiers; a couch contributes both of its identifiers. */
  seats: string[];
}

/** One line of the summary: a single seat or a couch. */
export interface TicketItem {
  row: number;
  /** `<column>` for a seat, `Couch <a>-<b>` for a couch. */
  seat: string;
  seatIds: string[];
  price: number;
}

const STORAGE_KEY = 'cinescope.booking';
const SEAT_ID_PATTERN = /^R(\d+)C(\d+)$/;

@Injectable({ providedIn: 'root' })
export class BookingStore {
  read(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw === null) {
      return null;
    }
    try {
      const booking = JSON.parse(raw) as Booking;
      return typeof booking.screeningId === 'number' && Array.isArray(booking.seats)
        ? booking
        : null;
    } catch {
      return null;
    }
  }

  write(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }

  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
  }
}

/**
 * Turns seat identifiers into the tickets of the summary, ordered by row and then by column.
 * Couches only exist in the couch row, where they are always the pairs of columns 1–2, 3–4, …
 */
export function ticketsFor(seats: readonly string[]): TicketItem[] {
  const columnsByRow = new Map<number, number[]>();
  for (const id of seats) {
    const match = SEAT_ID_PATTERN.exec(id);
    if (!match) {
      continue;
    }
    const row = Number(match[1]);
    const columns = columnsByRow.get(row) ?? [];
    columns.push(Number(match[2]));
    columnsByRow.set(row, columns);
  }

  const items: TicketItem[] = [];
  for (const row of [...columnsByRow.keys()].sort((a, b) => a - b)) {
    const columns = (columnsByRow.get(row) ?? []).sort((a, b) => a - b);
    for (let index = 0; index < columns.length; ) {
      const column = columns[index];
      const next = columns[index + 1];
      if (row === COUCH_ROW && column % 2 === 1 && next === column + 1) {
        items.push({
          row,
          seat: `Couch ${column}-${next}`,
          seatIds: [seatId(row, column), seatId(row, next)],
          price: COUCH_PRICE,
        });
        index += 2;
      } else {
        items.push({ row, seat: `${column}`, seatIds: [seatId(row, column)], price: seatPrice(row) });
        index += 1;
      }
    }
  }
  return items;
}

/** Lets a route be entered only with a booking in progress for the screening in the URL. */
export const bookingInProgressGuard: CanActivateFn = (route) => {
  const booking = inject(BookingStore).read();
  const screeningId = Number(route.paramMap.get('id'));
  if (booking && booking.screeningId === screeningId && booking.seats.length > 0) {
    return true;
  }
  return inject(Router).createUrlTree(['/']);
};

import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map, switchMap } from 'rxjs';
import { Movie, Screening } from './models';

const API_BASE_URL = 'http://localhost:3000';

export interface ScreeningWithMovie {
  screening: Screening;
  movie: Movie;
}

@Injectable({ providedIn: 'root' })
export class CinemaApi {
  private readonly http = inject(HttpClient);

  movies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${API_BASE_URL}/movies`);
  }

  movie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${API_BASE_URL}/movies/${id}`);
  }

  screeningsOn(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${API_BASE_URL}/screenings`, { params: { date } });
  }

  screening(id: string): Observable<Screening> {
    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${encodeURIComponent(id)}`);
  }

  /** A screening together with its movie; fails when either request fails. */
  screeningWithMovie(id: string): Observable<ScreeningWithMovie> {
    return this.screening(id).pipe(
      switchMap((screening) =>
        this.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
      ),
    );
  }
}

