 * booking replaces the previous one.
 */
private openBooking(screeningId: number): void {
  const existing = this.bookings.read();
  const seats = existing?.screeningId === screeningId ? existing.seats : [];
  this.bookings.write({ screeningId, seats });
  this.selectedIds.set(new Set(seats));
}

